-- 0077_games_chamo_check.sql — kiểm tra migration 0077 TRÊN DB THẬT, không để lại dữ liệu.
--
-- CÁCH CHẠY: áp 0074, 0075 rồi 0077, rồi dán TOÀN BỘ file này vào Supabase SQL Editor → Run.
--
-- ĐỌC KẾT QUẢ — script LUÔN kết thúc bằng lỗi, đó là cố ý (giống 0076_games_colat_check.sql):
--   ✅ "0077 CHECK OK — ..."  → mọi bước đạt. Lỗi này để Postgres HUỶ mọi thay đổi thử.
--   ❌ "SAI Ở BƯỚC ..."       → dừng ở bước đó, dán nguyên thông báo cho người viết migration.
--   ❌ lỗi khác               → cũng dán nguyên văn.
--
-- Cần: một CLB có HAI thành viên đã ghép tài khoản.
--
-- Ván mẫu (hằng v_ch) do luật JS lib/games/chamo.js sinh ra, mỗi ván kèm tuỳ chọn phòng — cỡ 3, 4, 5, cỡ viết 6.0 và
-- cỡ bậy (chuỗi, quá lớn) phải về 5 × 5 — trộn nước rác (sai lượt, kể cả chen vào lúc người kia đang được đi tiếp;
-- nét đã nối, nét dạng chuỗi, nét lẻ, ngoài bàn, null, sai khoá, đi sau khi hết ván, số viết dạng 5.0).
-- Kết quả có cả số ô mỗi bên. chamo.test.js đọc lại ĐÚNG khối này và chấm bằng JS → JS và SQL phải ra cùng kết quả.
-- Đổi luật thì sinh lại cả khối (node src/__tests__/games/fixtures.mjs), ĐỪNG sửa tay từng ván cho khớp.

DO $check$
DECLARE
  v_club  uuid;
  v_u1    uuid;
  v_u2    uuid;
  v_room  uuid;
  v_fx    jsonb;
  v_got   jsonb;
  v_want  jsonb;
  v_n     int := 0;
  v_err   text;
  r       game_rooms;
  v_ch CONSTANT jsonb := $ch$
[
