{"note":"chưa xong ván","result":null,"moves":[{"seat":0,"move":{"line":0}},{"seat":1,"move":{"line":"33"}},{"seat":1,"move":{"line":42}},{"seat":0,"move":{"line":52.5}},{"seat":0,"move":{"line":31}},{"seat":1,"move":{"line":-1}},{"seat":1,"move":{"line":53}},{"seat":0,"move":{"line":60}},{"seat":0,"move":{"line":43}},{"seat":1,"move":{"cell":48}},{"seat":1,"move":{"line":57}},{"seat":0,"move":null},{"seat":0,"move":{"line":58}},{"seat":1,"move":[35]},{"seat":1,"move":{"line":47}},{"seat":1,"move":{"line":38}},{"seat":0,"move":{"line":17}},{"seat":1,"move":{"line":58}},{"seat":1,"move":{"line":30}},{"seat":0,"move":{"line":"1"}},{"seat":0,"move":{"line":11}},{"seat":1,"move":{"line":52.5}},{"seat":1,"move":{"line":25}},{"seat":0,"move":{"line":-1}},{"seat":0,"move":{"line":19}},{"seat":1,"move":{"line":60}},{"seat":1,"move":{"line":9}},{"seat":0,"move":{"cell":38}},{"seat":0,"move":{"line":23}},{"seat":1,"move":null}]}
]
$ch$;
BEGIN
  /* ---------- 1. Có hàm chấm, client không gọi thẳng được ---------- */
  IF to_regprocedure('public.game_chamo_result(uuid)') IS NULL THEN
    RAISE EXCEPTION 'SAI Ở BƯỚC 1: chưa có game_chamo_result — đã chạy 0077 chưa?';
  END IF;
  IF has_function_privilege('authenticated', 'public.game_chamo_result(uuid)', 'EXECUTE')
     OR has_function_privilege('anon', 'public.game_chamo_result(uuid)', 'EXECUTE') THEN
    RAISE EXCEPTION 'SAI Ở BƯỚC 1: client gọi thẳng được hàm chấm';
  END IF;
  IF to_regprocedure('public.game_finish(uuid, jsonb)') IS NULL
     OR NOT has_function_privilege('authenticated', 'public.game_finish(uuid, jsonb)', 'EXECUTE') THEN
    RAISE EXCEPTION 'SAI Ở BƯỚC 1: thiếu game_finish hoặc authenticated không gọi được — đã chạy 0075 chưa?';
  END IF;

  /* ---------- 2. Tìm hai thành viên cùng CLB ---------- */
  SELECT a.club_id, a.user_id, b.user_id INTO v_club, v_u1, v_u2
    FROM club_members a JOIN club_members b ON b.club_id = a.club_id AND b.id <> a.id
   WHERE a.active AND b.active AND a.user_id IS NOT NULL AND b.user_id IS NOT NULL AND a.user_id <> b.user_id
   LIMIT 1;
  IF v_club IS NULL THEN RAISE EXCEPTION 'SAI Ở BƯỚC 2: cần một CLB có hai thành viên đã ghép tài khoản'; END IF;
  PERFORM set_config('request.jwt.claim.sub', v_u1::text, true);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_u1, 'role', 'authenticated')::text, true);

  /* ---------- 3. Từng ván mẫu: SQL chấm ra đúng như JS (cả số ô, cả cỡ bàn) ---------- */
  FOR v_fx IN SELECT value FROM jsonb_array_elements(v_ch) LOOP
    v_n := v_n + 1;
    v_room := game_create(v_club, 'chamo', COALESCE(v_fx -> 'options', '{}'::jsonb), false);
    INSERT INTO game_moves (room_id, seq, club_id, seat, move)
    SELECT v_room, e.ord, v_club, (e.value ->> 'seat')::smallint, e.value -> 'move'
      FROM jsonb_array_elements(v_fx -> 'moves') WITH ORDINALITY AS e(value, ord);
    v_got := game_chamo_result(v_room);
    v_want := NULLIF(v_fx -> 'result', 'null'::jsonb);
    IF v_got IS DISTINCT FROM v_want THEN
      RAISE EXCEPTION 'SAI Ở BƯỚC 3: ván mẫu % (%) — SQL chấm %, JS chấm %', v_n, v_fx ->> 'note', v_got, v_want;
    END IF;
  END LOOP;
  IF v_n = 0 THEN RAISE EXCEPTION 'SAI Ở BƯỚC 3: khối ván mẫu rỗng — chạy node src/__tests__/games/fixtures.mjs'; END IF;

  /* ---------- 4. game_finish tự tìm ra bản chấm Chấm ô, bỏ qua kết quả client bịa ---------- */
  SELECT value INTO v_fx FROM jsonb_array_elements(v_ch) WHERE value -> 'result' <> 'null'::jsonb LIMIT 1;
  v_room := game_create(v_club, 'chamo', COALESCE(v_fx -> 'options', '{}'::jsonb), false);
  PERFORM set_config('request.jwt.claim.sub', v_u2::text, true);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_u2, 'role', 'authenticated')::text, true);
  PERFORM game_join(v_room, 2);
  PERFORM set_config('request.jwt.claim.sub', v_u1::text, true);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_u1, 'role', 'authenticated')::text, true);
  PERFORM game_start(v_room, 2, 2);

  BEGIN
    PERFORM game_finish(v_room, '{"winners":[0],"draw":false}'::jsonb);
    RAISE EXCEPTION 'SAI Ở BƯỚC 4: chưa đi nước nào mà kết thúc được ván';
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS v_err = MESSAGE_TEXT;
    IF v_err <> 'games.err.notOver' THEN RAISE; END IF;
  END;

  INSERT INTO game_moves (room_id, seq, club_id, seat, move)
  SELECT v_room, e.ord, v_club, (e.value ->> 'seat')::smallint, e.value -> 'move'
    FROM jsonb_array_elements(v_fx -> 'moves') WITH ORDINALITY AS e(value, ord);
  PERFORM game_finish(v_room, '{"winners":[0,1],"draw":false}'::jsonb);
  SELECT * INTO r FROM game_rooms WHERE id = v_room;
  IF r.status <> 'finished' OR r.result IS DISTINCT FROM v_fx -> 'result' THEN
    RAISE EXCEPTION 'SAI Ở BƯỚC 4: phải lưu kết quả server chấm %, nhận % / %', v_fx -> 'result', r.status, r.result;
  END IF;

  RAISE EXCEPTION '0077 CHECK OK — % ván mẫu Chấm ô SQL chấm khớp JS (cả số ô, cả cỡ bàn) · game_finish tự chấm Chấm ô', v_n;
END;
$check$;
